import {chooseLibrary,rememberedLibrary,requireLibrary,saveFolderVariant} from './sector-folder.js';
export function installSectorSave({getDocument,status}){
 const button=document.createElement('button');button.id='save-sector-variant';button.textContent='Save as new sector variant';document.querySelector('.remote-view').append(button);
 const dialog=document.createElement('dialog');dialog.id='sector-save-dialog';dialog.innerHTML='<form method="dialog"><h2>Save a new sector variant</h2><p id="sector-save-location"></p><button type="button" id="sector-choose-folder">Choose map library folder</button><p id="sector-folder-location">No portable folder selected.</p><label>Variant name<input id="sector-variant-name" required pattern="[a-z0-9][a-z0-9-]{0,119}" placeholder="town-west-market"></label><label>Progress<select id="sector-variant-status"><option value="in-progress">In progress</option><option value="authored">Ready for review</option></select></label><p>Readiness is an authoring label. Campaign compatibility still requires review. Existing variants are never overwritten.</p><p id="sector-save-result" role="status"></p><button type="button" id="sector-save-submit">Save variant</button><button>Close</button></form>';document.body.append(dialog);const $=id=>document.getElementById(id);let token=null,id=null;rememberedLibrary().then(h=>{if(h)$('sector-folder-location').textContent='Selected folder: '+h.name;});
 $('sector-choose-folder').onclick=async()=>{try{const h=await chooseLibrary();$('sector-folder-location').textContent='Selected folder: '+h.name;$('sector-save-result').textContent='Ready to save into the selected map library.';$('sector-save-submit').disabled=false;}catch(e){$('sector-save-result').textContent=e.message;}};
 button.onclick=async()=>{const d=getDocument(),params=new URLSearchParams(location.search);id=d?.map.sectorTemplate?.id||params.get('sectorTemplate');if(!d||d.block||!id)return status('Open a sector configuration from the map library before saving a variant.');const t=d.map.sectorTemplate?.transform;if(t&&(t.turns||t.mirror)||Number(params.get('orientation')||0)!==0)return status('Open this configuration at 0° to save a variant with matching entrances.');dialog.showModal();$('sector-save-location').textContent='Configuration: '+id;$('sector-save-result').textContent='Connecting to the local authoring workspace…';$('sector-save-submit').disabled=true;try{const h=await rememberedLibrary();if(h){await requireLibrary();$('sector-folder-location').textContent='Selected folder: '+h.name;$('sector-save-result').textContent='Saves directly into your selected folder.';$('sector-save-submit').disabled=false;return;}const r=await fetch('/api/sector-authoring');if(!r.ok)throw Error();const data=await r.json();if(!data.token)throw Error();token=data.token;$('sector-save-result').textContent='Saves to workspace folder '+data.source+' and updates the map library.';$('sector-save-submit').disabled=false;}catch(e){$('sector-save-result').textContent=e.message||'Choose your map library folder. If folder access is unavailable, use Export JSON or the local workspace server.';}};
 $('sector-save-submit').onclick=async()=>{if(!$('sector-variant-name').reportValidity())return;const submit=$('sector-save-submit');submit.disabled=true;try{if(await rememberedLibrary()){const result=await saveFolderVariant(await requireLibrary(true),{id,name:$('sector-variant-name').value,status:$('sector-variant-status').value,map:JSON.parse(getDocument().export())});$('sector-save-result').textContent='Saved: '+result.path;status('Saved to selected folder. Refresh its library view to see the variant.');return;}const r=await fetch('/api/sector-authoring/variants',{method:'POST',headers:{'Content-Type':'application/json','X-Sector-Token':token},body:JSON.stringify({id,name:$('sector-variant-name').value,status:$('sector-variant-status').value,map:JSON.parse(getDocument().export())})});const result=await r.json();if(!r.ok)throw Error(result.error);$('sector-save-result').textContent='Saved: '+result.path;status('Sector variant saved. Refresh the map library to see it.');}catch(e){$('sector-save-result').textContent=e.message;}finally{submit.disabled=false;}};
}
